import{_ as t,o as a,c as o,a2 as s}from"./chunks/framework.Cdp8-jB6.js";const p=JSON.parse('{"title":"Adding a fleet asset — runbook","description":"","frontmatter":{},"headers":[],"relativePath":"guides/fleet-addition-runbook.md","filePath":"guides/fleet-addition-runbook.md"}'),d={name:"guides/fleet-addition-runbook.md"};function r(i,e,n,l,c,h){return a(),o("div",null,[...e[0]||(e[0]=[s(`<h1 id="adding-a-fleet-asset-—-runbook" tabindex="-1">Adding a fleet asset — runbook <a class="header-anchor" href="#adding-a-fleet-asset-—-runbook" aria-label="Permalink to &quot;Adding a fleet asset — runbook&quot;">​</a></h1><p>The prescribed path for authoring a <strong>fleet asset</strong> — a launcher, spacecraft, lander, rover, station, launch-site, observatory, space-suit, etc. Companion to the <a href="./mission-addition-runbook">mission-addition runbook</a> and <a href="./../../scripts/IMAGE-PIPELINE"><code>scripts/IMAGE-PIPELINE.md</code></a>. <strong>A fleet asset is real content — never a stub.</strong> If a mission references a fleet id that doesn&#39;t exist, author it here first; do not auto-generate an empty record.</p><p>Worked example: <strong>SLS Block 1B</strong> (<code>sls-block-1b</code>, launcher) — the Exploration-Upper-Stage variant Artemis 4 flies, which does not yet exist as an entry.</p><h2 id="when-you-need-this" tabindex="-1">When you need this <a class="header-anchor" href="#when-you-need-this" aria-label="Permalink to &quot;When you need this&quot;">​</a></h2><ul><li>A new mission&#39;s <code>fleet_refs[]</code> points at a launcher / spacecraft / launch-site that has no entry (Artemis 4 → <code>sls-block-1b</code>, <code>gateway</code>, <code>i-hab</code>, <code>starship-hls</code>).</li><li>A new vehicle/station/suit enters service.</li></ul><p><strong>Agent orchestration:</strong> the mission-add flow should <strong>detect</strong> the missing fleet ids and <strong>fan out one fleet-authoring sub-agent per asset</strong> (they&#39;re independent — parallelize), each running this runbook, then resume the mission once they land. It must NOT stub them (see the mission runbook&#39;s &quot;Design intent&quot;).</p><h2 id="the-12-categories" tabindex="-1">The 12 categories <a class="header-anchor" href="#the-12-categories" aria-label="Permalink to &quot;The 12 categories&quot;">​</a></h2><p><code>cargo-spacecraft · constellation · crewed-spacecraft · lander · launch-site · launcher · observatory · orbiter · rover · space-suit · station</code></p><p>The <code>category</code> field + the directory <code>static/data/fleet/&lt;category&gt;/</code> must agree.</p><h2 id="touchpoints-in-order" tabindex="-1">Touchpoints (in order) <a class="header-anchor" href="#touchpoints-in-order" aria-label="Permalink to &quot;Touchpoints (in order)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Touchpoint</th><th>File</th><th>Required</th><th>Notes</th></tr></thead><tbody><tr><td>1</td><td><strong>Base entry</strong></td><td><code>static/data/fleet/&lt;category&gt;/&lt;id&gt;.json</code></td><td>✅</td><td>schema <code>fleet-entry.schema.json</code></td></tr><tr><td>2</td><td><strong>Index entry</strong></td><td><code>static/data/fleet/index.json</code></td><td>✅</td><td>schema <code>fleet-index.schema.json</code></td></tr><tr><td>3</td><td><strong>en-US overlay</strong></td><td><code>i18n-src/en-US/fleet/&lt;category&gt;/&lt;id&gt;.json</code></td><td>✅</td><td>schema <code>fleet-overlay.schema.json</code></td></tr><tr><td>4</td><td><strong>LEARN links</strong></td><td><code>links[]</code> in the base entry</td><td>✅ (≥1)</td><td>agency page &gt; Wikipedia (ADR-051)</td></tr><tr><td>5</td><td><strong><code>linked_missions[]</code></strong></td><td>base entry</td><td>auto</td><td><strong>Do NOT hand-author</strong> — it&#39;s the reverse of missions&#39; <code>fleet_refs</code>; <code>npx tsx scripts/migrate-fleet-linked-missions.ts</code> derives it</td></tr><tr><td>6</td><td><strong>Hero + gallery images</strong></td><td><code>static/images/fleet-galleries/&lt;id&gt;/…</code></td><td>✅ hero (zero-gap policy)</td><td>the <a href="./../../scripts/IMAGE-PIPELINE#adding-a-new-gallery-image">image pipeline</a></td></tr><tr><td>7</td><td><strong>Translations (all 14 locales)</strong></td><td><code>i18n-src/&lt;locale&gt;/fleet/&lt;category&gt;/&lt;id&gt;.json</code></td><td>✅ <strong>required</strong> (core content)</td><td><code>scripts/translate-i18n-gaps.mjs</code></td></tr><tr><td>8</td><td><strong>3D surface model</strong></td><td><code>src/lib/{moon,mars}-lander-models.ts</code></td><td>only landers/rovers</td><td>reuse an existing builder if the shape fits (ADR-072); don&#39;t add ad-hoc</td></tr></tbody></table><h3 id="_1–3-·-core-data" tabindex="-1">1–3 · Core data <a class="header-anchor" href="#_1–3-·-core-data" aria-label="Permalink to &quot;1–3 · Core data&quot;">​</a></h3><p>Base entry required (<code>fleet-entry.schema.json</code>): <code>id, name, category, agency, country, manufacturer, first_flight, status, era, epoch, credit, links</code>. Index required (<code>fleet-index.schema.json</code>): <code>id, name, category, agency, country, era, epoch, status, first_flight, tagline</code>. Overlay required (<code>fleet-overlay.schema.json</code>): <code>description</code> (+ <code>name</code>, <code>tagline</code>, <code>best_known_for</code> carried alongside). <code>id</code> is <code>^[a-z0-9-]+$</code>; copy the shape from the nearest analog (<code>sls-block-1b</code> authored from <code>sls-block-1.json</code>). <code>era</code> is a range (<code>&quot;2011-now&quot;</code>); <code>epoch</code> is a program tag (<code>&quot;lunar-return&quot;</code>).</p><h3 id="_5-·-symmetry-is-derived-not-authored" tabindex="-1">5 · Symmetry is derived, not authored <a class="header-anchor" href="#_5-·-symmetry-is-derived-not-authored" aria-label="Permalink to &quot;5 · Symmetry is derived, not authored&quot;">​</a></h3><p><code>linked_missions[]</code> mirrors every mission whose <code>fleet_refs[]</code> names this asset. Author the <strong>mission</strong> side (<code>fleet_refs</code>), then run <code>migrate-fleet-linked-missions.ts</code> — it populates both directions. <code>validate-data</code> fails-closed on asymmetry and prints the command.</p><h3 id="_6-·-images-—-fleet-assets-carry-zero-hero-gaps" tabindex="-1">6 · Images — fleet assets carry ZERO hero gaps <a class="header-anchor" href="#_6-·-images-—-fleet-assets-carry-zero-hero-gaps" aria-label="Permalink to &quot;6 · Images — fleet assets carry ZERO hero gaps&quot;">​</a></h3><p><code>validate-hero-coverage</code> fails-closed if <code>static/images/fleet-galleries/&lt;id&gt;/01.webp</code> is absent (<code>FLEET_KNOWN_GAPS</code> is intentionally empty). Source the hero + gallery through the image pipeline (agency-first → <code>masters/</code> → WebP ladder → provenance → counts), <strong>staged for per-image approval</strong> at <code>/dev/staging</code>. Native-language sourcing rules apply for non-Western agencies (AGENTS.md).</p><h2 id="validation-the-done-signal" tabindex="-1">Validation = the done-signal <a class="header-anchor" href="#validation-the-done-signal" aria-label="Permalink to &quot;Validation = the done-signal&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> validate-data</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # schema + overlay-completeness + fleet↔mission symmetry + hero coverage + links</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> preflight</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">         # full pre-push</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> preview</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">           # eyeball /fleet row + detail panel at localhost</span></span></code></pre></div><h2 id="gotchas" tabindex="-1">Gotchas <a class="header-anchor" href="#gotchas" aria-label="Permalink to &quot;Gotchas&quot;">​</a></h2><ul><li><strong>Never stub.</strong> Every required field is real content — no <code>&quot;TBD&quot;</code> / empty specs. An empty fleet entry is the rot the five-gate rule (AGENTS.md) exists to stop.</li><li><strong><code>category</code> ↔ directory must match</strong>, and both must be one of the 12.</li><li><strong>Don&#39;t hand-author <code>linked_missions</code></strong> — derive it; hand-editing drifts.</li><li><strong>Hero image is mandatory</strong> (zero-gap policy) — source real imagery (or agency render), approval-gated.</li><li><strong>Localization is core content, not optional</strong> — all 14 locales (<code>translate-i18n-gaps.mjs</code>), same tier as the hero image. en-US passing <code>validate-data</code> is a fallback floor, not done; ship the translations in the same PR.</li><li><strong>Reuse 3D builders</strong> — a new lander/rover shares an existing builder unless genuinely novel (ADR-072); adding one ad-hoc is blocked by AGENTS.md.</li></ul>`,21)])])}const u=t(d,[["render",r]]);export{p as __pageData,u as default};
